<?php
declare(strict_types=1);
namespace App\Modules\Subcontracts\Repositories;
use App\Core\Database\Database;
use App\Modules\Subcontracts\DTOs\SubcontractData;
final class SubcontractRepository
{
    public function __construct(private readonly Database $db) {}
    public function find(int $id): ?array { $r=$this->db->execute('SELECT s.*,p.project_code,p.name project_name,v.vendor_code,v.name vendor_name,ws.section_code work_section_code,ws.name work_section_name FROM subcontracts s JOIN projects p ON p.id=s.project_id JOIN vendors v ON v.id=s.vendor_id LEFT JOIN work_sections ws ON ws.id=s.work_section_id WHERE s.id=? LIMIT 1',[$id]); $x=$r instanceof \mysqli_result?$r->fetch_assoc():null; return is_array($x)?$x:null; }
    public function project(int $id): bool { $r=$this->db->execute('SELECT 1 FROM projects WHERE id=? LIMIT 1',[$id]); return $r instanceof \mysqli_result&&$r->num_rows>0; }
    public function workSection(int $id): bool { $r=$this->db->execute('SELECT 1 FROM work_sections WHERE id=? AND is_active=1 LIMIT 1',[$id]); return $r instanceof \mysqli_result&&$r->num_rows>0; }
    public function vendor(int $id,bool $active): bool { $r=$this->db->execute("SELECT 1 FROM vendors WHERE id=? AND vendor_type IN('subcontractor','both')".($active?' AND is_active=1':'').' LIMIT 1',[$id]); return $r instanceof \mysqli_result&&$r->num_rows>0; }
    public function vendorInWorkSection(int $vendorId,int $sectionId): bool { $r=$this->db->execute('SELECT 1 FROM vendor_work_sections WHERE vendor_id=? AND work_section_id=? LIMIT 1',[$vendorId,$sectionId]); return $r instanceof \mysqli_result&&$r->num_rows>0; }
    public function create(string $code,SubcontractData $data): int { $this->db->execute("INSERT INTO subcontracts(subcontract_code,project_id,work_section_id,vendor_id,pricing_method,title,description,contract_date,start_date,expected_end_date,status,notes) VALUES(?,?,?,?,?,?,?,?,?,?,'draft',?)",[$code,$data->projectId,$data->workSectionId,$data->vendorId,'boq',$data->title,$data->description,$data->contractDate,$data->startDate,$data->endDate,$data->notes]); return (int)$this->db->connection()->insert_id; }
    public function createScope(int $subcontractId,int $workSectionId): int { $this->db->execute("INSERT INTO subcontract_boqs(subcontract_id,status) VALUES(?,'draft')",[$subcontractId]);$boqId=(int)$this->db->connection()->insert_id;$this->db->execute('INSERT INTO subcontract_boq_sections(subcontract_boq_id,work_section_id,section_code,title,sort_order) SELECT ?,id,section_code,name,1 FROM work_sections WHERE id=?',[$boqId,$workSectionId]);return(int)$this->db->connection()->insert_id; }
    public function unit(int $id): ?array { $r=$this->db->execute('SELECT id,code,name_ar,symbol_ar FROM units WHERE id=? AND is_active=1 LIMIT 1',[$id]);$x=$r instanceof \mysqli_result?$r->fetch_assoc():null;return is_array($x)?$x:null; }
    public function createScopeItem(int $sectionId,\App\Modules\SubcontractBoq\DTOs\BoqItemData $item,array $unit,int $sortOrder): void { $this->db->execute('INSERT INTO subcontract_boq_items(subcontract_boq_section_id,description,pricing_type,unit_id,unit_name,unit_symbol,quantity,unit_rate,lump_sum_amount,sort_order,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$sectionId,$item->description,$item->pricingType,$item->unitId,$unit['name_ar'],$unit['symbol_ar'],$item->quantity,$item->unitRate,$item->lumpSumAmount,$sortOrder,$item->notes]); }
    public function update(int $id,SubcontractData $data,bool $commercial): void { if($commercial)$this->db->execute('UPDATE subcontracts SET project_id=?,work_section_id=?,vendor_id=?,pricing_method=?,title=?,description=?,contract_date=?,start_date=?,expected_end_date=?,notes=? WHERE id=?',[$data->projectId,$data->workSectionId,$data->vendorId,'boq',$data->title,$data->description,$data->contractDate,$data->startDate,$data->endDate,$data->notes,$id]); else $this->db->execute('UPDATE subcontracts SET start_date=?,expected_end_date=?,notes=? WHERE id=?',[$data->startDate,$data->endDate,$data->notes,$id]); }
    public function status(int $id,string $status): void { $this->db->execute('UPDATE subcontracts SET status=? WHERE id=?',[$status,$id]); }
    public function boq(int $id): ?array { $r=$this->db->execute('SELECT status FROM subcontract_boqs WHERE subcontract_id=? LIMIT 1',[$id]); $x=$r instanceof \mysqli_result?$r->fetch_assoc():null; return is_array($x)?$x:null; }
    public function refs(): array { foreach(['projects'=>'SELECT id,project_code,name FROM projects ORDER BY project_code','work_sections'=>'SELECT id,section_code,name FROM work_sections WHERE is_active=1 ORDER BY sort_order,section_code','vendors'=>"SELECT v.id,v.vendor_code,v.name,v.is_active FROM vendors v WHERE v.vendor_type IN('subcontractor','both') ORDER BY v.name",'units'=>'SELECT id,code,name_ar FROM units WHERE is_active=1 ORDER BY sort_order'] as $key=>$sql){$r=$this->db->execute($sql);$references[$key]=$r instanceof \mysqli_result?$r->fetch_all(MYSQLI_ASSOC):[];} return $references; }
    public function vendorsForWorkSection(int $sectionId): array { $r=$this->db->execute("SELECT v.id,v.vendor_code,v.name,v.is_active FROM vendors v JOIN vendor_work_sections vws ON vws.vendor_id=v.id WHERE vws.work_section_id=? AND v.is_active=1 AND v.vendor_type IN('subcontractor','both') ORDER BY v.name",[$sectionId]); return $r instanceof \mysqli_result?$r->fetch_all(MYSQLI_ASSOC):[]; }
    public function workspaceStats(int $id): array
    {
        $sql = "SELECT b.id boq_id,b.status boq_status,
            (SELECT COUNT(*) FROM subcontract_progress_certificates c WHERE c.subcontract_id=s.id) certificate_count,
            (SELECT COUNT(*) FROM subcontract_progress_certificates c WHERE c.subcontract_id=s.id AND c.status='draft') draft_certificate_count,
            (SELECT COUNT(*) FROM subcontract_payments p WHERE p.subcontract_id=s.id) payment_count,
            (SELECT COUNT(*) FROM subcontract_payments p WHERE p.subcontract_id=s.id AND p.status='draft') draft_payment_count
            FROM subcontracts s LEFT JOIN subcontract_boqs b ON b.subcontract_id=s.id WHERE s.id=? LIMIT 1";
        $result = $this->db->execute($sql, [$id]);
        $row = $result instanceof \mysqli_result ? $result->fetch_assoc() : null;
        return is_array($row) ? $row : [];
    }
    public function printScope(int $id): array { $r=$this->db->execute('SELECT bs.section_code,bs.title section_title,i.description,i.pricing_type,i.unit_name,i.unit_symbol,i.quantity,i.unit_rate,i.lump_sum_amount,i.line_total FROM subcontract_boqs b JOIN subcontract_boq_sections bs ON bs.subcontract_boq_id=b.id JOIN subcontract_boq_items i ON i.subcontract_boq_section_id=bs.id WHERE b.subcontract_id=? ORDER BY bs.sort_order,i.sort_order,i.id',[$id]);return$r instanceof \mysqli_result?$r->fetch_all(MYSQLI_ASSOC):[]; }
    public function scopeTotal(int $id): string { $r=$this->db->execute('SELECT COALESCE(SUM(i.line_total),0) total FROM subcontract_boqs b JOIN subcontract_boq_sections bs ON bs.subcontract_boq_id=b.id JOIN subcontract_boq_items i ON i.subcontract_boq_section_id=bs.id WHERE b.subcontract_id=?',[$id]);return(string)(($r instanceof \mysqli_result?$r->fetch_assoc():[])['total']??'0.00'); }
    public function all(): array { $r=$this->db->execute('SELECT s.id,s.subcontract_code,s.project_id,s.work_section_id,s.vendor_id,p.name project_name,v.name vendor_name,ws.name work_section_name,s.title,s.contract_value,s.contract_date,s.status FROM subcontracts s JOIN projects p ON p.id=s.project_id JOIN vendors v ON v.id=s.vendor_id LEFT JOIN work_sections ws ON ws.id=s.work_section_id ORDER BY s.id DESC'); return $r instanceof \mysqli_result?$r->fetch_all(MYSQLI_ASSOC):[]; }
}
